import json
from pathlib import Path
class ConstitutionalCoverageFoundationReporter:
    def write(self,assessment,output_directory:Path):
        output_directory.mkdir(parents=True,exist_ok=True); artifacts={"constitutional_coverage_assessment.json":assessment.to_dict(),"constitutional_coverage_policy.json":{"schema_version":assessment.schema_version,"coverage_fingerprint":assessment.coverage_fingerprint,"policy":assessment.policy.to_dict()},"constitutional_coverage_metrics.json":{"schema_version":assessment.schema_version,"coverage_fingerprint":assessment.coverage_fingerprint,"statistics":assessment.statistics.to_dict(),"article_metrics":[x.to_dict() for x in assessment.article_metrics],"domain_metrics":[x.to_dict() for x in assessment.domain_metrics]},"constitutional_coverage_traceability.json":{"repository_fingerprint":assessment.repository_fingerprint,"extraction_fingerprint":assessment.extraction_fingerprint,"analysis_fingerprint":assessment.analysis_fingerprint,"ratification_fingerprint":assessment.ratification_fingerprint,"compliance_fingerprint":assessment.compliance_fingerprint,"certification_fingerprint":assessment.certification_fingerprint,"audit_fingerprint":assessment.audit_fingerprint,"coverage_fingerprint":assessment.coverage_fingerprint}}; written=[]
        for n,p in artifacts.items():
            q=output_directory/n; q.write_text(json.dumps(p,indent=2,sort_keys=True,ensure_ascii=False)+"\n",encoding="utf-8"); written.append(q)
        s=assessment.statistics; q=output_directory/'constitutional_coverage_foundation_report.md'; q.write_text(f"# Genesis VII-C4.3 Pack 1 — Coverage Intelligence Foundation\n\n**Coverage fingerprint:** `{assessment.coverage_fingerprint}`\n\n- Articles total: {s.articles_total}\n- Articles exercised: {s.articles_exercised}\n- Articles underutilized: {s.articles_underutilized}\n- Articles unused: {s.articles_unused}\n- Article coverage ratio: {s.article_coverage_ratio:.2%}\n- Repository artifacts: {s.artifacts_total}\n- Governed artifacts: {s.artifacts_governed}\n- Ungoverned artifacts: {s.artifacts_ungoverned}\n- Repository coverage ratio: {s.repository_coverage_ratio:.2%}\n- Diagnostics: {len(assessment.diagnostics)}\n",encoding="utf-8"); written.append(q); return tuple(written)
